function getLang() {
  return localStorage.getItem(LANG_STORAGE_KEY) || "en";
}

function t(key, vars) {
  const lang = getLang();
  let str = (TRANSLATIONS[lang] && TRANSLATIONS[lang][key]) || TRANSLATIONS.fr[key] || key;
  if (vars) {
    Object.keys(vars).forEach((k) => {
      str = str.replace(`{${k}}`, vars[k]);
    });
  }
  return str;
}
window.t = t;
window.getLang = getLang;

function applyStaticTranslations() {
  document.documentElement.lang = getLang();
  document.documentElement.dir = getLang() === "ar" ? "rtl" : "ltr";
  document.title = t("doc.title");

  document.querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = t(el.dataset.i18n);
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    el.placeholder = t(el.dataset.i18nPlaceholder);
  });
  document.querySelectorAll("[data-i18n-title]").forEach((el) => {
    el.title = t(el.dataset.i18nTitle);
  });

  updateLangButton();
}

function updateLangButton() {
  const langBtn = document.getElementById("lang-btn");
  if (langBtn) langBtn.innerHTML = FLAG_SVGS[getLang()];
  document.querySelectorAll(".lang-option").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.lang === getLang());
  });
}

function initLangOptionFlags() {
  document.querySelectorAll(".lang-option").forEach((btn) => {
    const slot = btn.querySelector(".flag-icon-slot");
    if (slot) slot.innerHTML = FLAG_SVGS[btn.dataset.lang] || "";
  });
}

function setLang(lang) {
  if (!TRANSLATIONS[lang]) return;
  localStorage.setItem(LANG_STORAGE_KEY, lang);
  applyStaticTranslations();
  document.dispatchEvent(new CustomEvent("languagechange"));
}
window.setLang = setLang;

// ---- Language switcher UI ----
const langBtn = document.getElementById("lang-btn");
const langMenu = document.getElementById("lang-menu");

langBtn.addEventListener("click", (e) => {
  e.stopPropagation();
  langMenu.hidden = !langMenu.hidden;
});

langMenu.querySelectorAll(".lang-option").forEach((btn) => {
  btn.addEventListener("click", () => {
    setLang(btn.dataset.lang);
    langMenu.hidden = true;
  });
});

document.addEventListener("click", (e) => {
  if (!langMenu.hidden && !langMenu.contains(e.target) && e.target !== langBtn) {
    langMenu.hidden = true;
  }
});

document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !langMenu.hidden) langMenu.hidden = true;
});

initLangOptionFlags();
applyStaticTranslations();
